// Local state — only this component needs it
function Toggle() {
  const [isOn, setIsOn] = useState(false);
  return <button onClick={() => setIsOn(!isOn)}>{isOn ? 'ON' : 'OFF'}</button>;
}

// Shared state — lift to the nearest common parent
function Parent() {
  const [count, setCount] = useState(0);
  return (
    <div>
      <Display count={count} />
      <Incrementor onIncrement={() => setCount(count + 1)} />
    </div>
  );
}

// Before: state trapped in one child
function TempInput({ scale }) {
  const [temp, setTemp] = useState(0);
  // Sibling cannot read this state!
}

// After: state lifted to parent
function Calculator() {
  const [temp, setTemp] = useState(0);
  const [scale, setScale] = useState('c');

  return (
    <>
      <TempInput temp={temp} scale="c" onChange={setTemp} />
      <TempInput temp={temp} scale="f" onChange={setTemp} />
    </>
  );
}

// Separate states — must update both manually
const [x, setX] = useState(0);
const [y, setY] = useState(0);

// Grouped state — update atomically
const [position, setPosition] = useState({ x: 0, y: 0 });

const move = (dx, dy) => {
  setPosition((prev) => ({ x: prev.x + dx, y: prev.y + dy }));
};

// WRONG — duplicated state
function Cart({ items }) {
  const [total, setTotal] = useState(0);
  useEffect(() => {
    setTotal(items.reduce((sum, i) => sum + i.price, 0));
  }, [items]);
}

// CORRECT — calculate during render
function Cart({ items }) {
  const total = items.reduce((sum, i) => sum + i.price, 0);
}
